Let IG2 : inv_G X2 st2 LS2 := proj1 (proj2 (proj2 (proj2 (proj2 INV2)))).
Let IS2 : inv_S X2 st2 BL := proj1 (proj2 (proj2 (proj2 (proj2 (proj2 INV2))))).

